fn to_base36(mut n: u32) -> String {
    if n == 0 { return "0".into(); }
    const DIGITS: &[u8] = b"REDACTED";
    let mut buf = Vec::new();
    while n > 0 { buf.push(DIGITS[(n % 36) as usize]); n /= 36; }
